const p = new PrismaClient();
(async () => {
  const userCount = await p.user.count();
  const identityCount = await p.authIdentity.count();
  const projectCount = await p.project.count();
  const taskCount = await p.task.count();
  console.log('users:', userCount);
  console.log('auth identities:', identityCount);
  console.log('projects:', projectCount);
  console.log('tasks:', taskCount);

  // Make sure no duplicate users
  const users = await p.user.findMany({ include: { auth: { include: { identities: true } } } });
  for (const u of users) {
    console.log(\`user \${u.id}: \${u.auth.identities[0].providerUserId}\`);
  }
  await p.\$disconnect();
})();
